1. use std::cmp::Ordering;
2. 
3. use semver::Version;
4. 
5. use crate::commands::UpgradeArgs;
6. use crate::exit_code::CliExitCode;
7. 
8. #[derive(Clone, Debug, Eq, PartialEq)]
9. pub(crate) struct ReleaseAsset {
10.     pub(crate) name: String,
11. }
12. 
13. #[derive(Clone, Copy, Debug, Eq, PartialEq)]
14. pub(crate) enum VersionStatus {
15.     UpgradeAvailable,
16.     AlreadyCurrent,
17.     CurrentIsNewer,
18. }
19. 
20. pub(crate) async fn execute(args: UpgradeArgs) -> Result<CliExitCode, crate::CliError> {
21.     let _ = (args.check, args.force);
22.     println!("upgrade not yet available, re-run the install script");
23.     Ok(CliExitCode::Success)
24. }
25. 
26. pub(crate) fn select_asset<'a>(assets: &'a [ReleaseAsset]) -> Option<&'a ReleaseAsset> {
27.     select_asset_for_platform(assets, std::env::consts::OS, std::env::consts::ARCH)
28. }
29. 
30. fn select_asset_for_platform<'a>(
31.     assets: &'a [ReleaseAsset],
32.     os: &str,
33.     arch: &str,
34. ) -> Option<&'a ReleaseAsset> {
35.     let target = target_triple(os, arch)?;
36.     assets.iter().find(|asset| asset.name.contains(target))
37. }
38. 
39. fn target_triple(os: &str, arch: &str) -> Option<&'static str> {
40.     match (os, arch) {
41.         ("linux", "x86_64") => Some("x86_64-unknown-linux-gnu"),
42.         ("macos", "aarch64") => Some("aarch64-apple-darwin"),
43.         ("macos", "x86_64") => Some("x86_64-apple-darwin"),
44.         _ => None,
45.     }
46. }
47. 
48. pub(crate) fn current_version_status(tag_name: &str) -> Result<VersionStatus, semver::Error> {
49.     compare_versions(env!("CARGO_PKG_VERSION"), tag_name)
50. }
51. 
52. fn compare_versions(
53.     current_version: &str,
54.     release_tag_name: &str,
55. ) -> Result<VersionStatus, semver::Error> {
56.     let current = Version::parse(current_version)?;
57.     let release = Version::parse(
58.         release_tag_name
59.             .strip_prefix('v')
60.             .unwrap_or(release_tag_name),
61.     )?;
62. 
63.     Ok(match release.cmp(&current) {
64.         Ordering::Greater => VersionStatus::UpgradeAvailable,
65.         Ordering::Equal => VersionStatus::AlreadyCurrent,
66.         Ordering::Less => VersionStatus::CurrentIsNewer,
67.     })
68. }
69. 
70. #[cfg(test)]
71. mod tests {
72.     use super::*;
73. 
74.     fn asset(name: &str) -> ReleaseAsset {
75.         ReleaseAsset {
76.             name: name.to_owned(),
77.         }
78.     }
79. 
80.     #[test]
81.     fn target_triple_maps_supported_platforms() {
82.         assert_eq!(
83.             target_triple("linux", "x86_64"),
84.             Some("x86_64-unknown-linux-gnu")
85.         );
86.         assert_eq!(
87.             target_triple("macos", "aarch64"),
88.             Some("aarch64-apple-darwin")
89.         );
90.         assert_eq!(
91.             target_triple("macos", "x86_64"),
92.             Some("x86_64-apple-darwin")
93.         );
94.     }
95. 
96.     #[test]
97.     fn target_triple_returns_none_for_unknown_platform() {
98.         assert_eq!(target_triple("freebsd", "x86_64"), None);
99.         assert_eq!(target_triple("linux", "riscv64"), None);
100.     }
101. 
102.     #[test]
103.     fn select_asset_matches_supported_platforms() {
104.         let assets = [
105.             asset("derrick-aarch64-apple-darwin.tar.gz"),
106.             asset("derrick-x86_64-apple-darwin.tar.gz"),
107.             asset("derrick-x86_64-unknown-linux-gnu.tar.gz"),
108.         ];
109. 
110.         assert_eq!(
111.             select_asset_for_platform(&assets, "linux", "x86_64"),
112.             Some(&assets[2])
113.         );
114.         assert_eq!(
115.             select_asset_for_platform(&assets, "macos", "aarch64"),
116.             Some(&assets[0])
117.         );
118.         assert_eq!(
119.             select_asset_for_platform(&assets, "macos", "x86_64"),
120.             Some(&assets[1])
121.         );
122.     }
123. 
124.     #[test]
125.     fn select_asset_returns_none_for_unknown_platform() {
126.         let assets = [asset("derrick-x86_64-unknown-linux-gnu.tar.gz")];
127.         assert_eq!(
128.             select_asset_for_platform(&assets, "windows", "x86_64"),
129.             None
130.         );
131.     }
132. 
133.     #[test]
134.     fn select_asset_uses_current_platform() {
135.         let Some(target) = target_triple(std::env::consts::OS, std::env::consts::ARCH) else {
136.             return;
137.         };
138.         let assets = [asset(&format!("derrick-{target}.tar.gz"))];
139.         assert_eq!(select_asset(&assets), Some(&assets[0]));
140.     }
141. 
142.     #[test]
143.     fn version_status_reports_upgrade_available_for_newer_release() {
144.         assert_eq!(
145.             compare_versions("1.0.0", "v1.0.1"),
146.             Ok(VersionStatus::UpgradeAvailable)
147.         );
148.     }
149. 
150.     #[test]
151.     fn version_status_reports_already_current_for_equal_release() {
152.         assert_eq!(
153.             compare_versions("1.0.0", "v1.0.0"),
154.             Ok(VersionStatus::AlreadyCurrent)
155.         );
156.     }
157. 
158.     #[test]
159.     fn version_status_reports_current_newer_for_older_release() {
160.         assert_eq!(
161.             compare_versions("1.0.1", "v1.0.0"),
162.             Ok(VersionStatus::CurrentIsNewer)
163.         );
164.     }
165. 
166.     #[test]
167.     fn version_status_treats_prerelease_as_less_than_stable() {
