 pub(crate) mod uninstall;
 pub(crate) mod upgrade;

 #[derive(Debug, Parser)]
 #[command(name = "derrick", version, about = "Derrick orchestration CLI")]
 pub(crate) struct Cli {
     #[command(subcommand)]
     pub(crate) command: Command,
 }

 #[derive(Debug, Subcommand)]
 pub(crate) enum Command {
     /// Shorthand for `run add-feature` — prompt is a positional argument.
     Add(AddArgs),
     Init(InitArgs),
     Status(StatusArgs),
     Doctor(DoctorArgs),
     Run(RunArgs),
     Completions(CompletionsArgs),
     Ticket(TicketArgs),
     Foreman(ForemanArgs),
     Stack(StackArgs),
     Observe(ObserveArgs),
     Uninstall(UninstallArgs),
     /// [reserved] Binary self-update (not yet implemented).
     Upgrade(UpgradeArgs),
     Scrub(ScrubArgs),
     Caveman(CavemanArgs),
     Gain(GainArgs),
     /// Switch the repo's substrate mode in-place (e.g. solo → crew).
     Switch(SwitchArgs),
 }

 /// Arguments for `derrick add` — positional prompt shorthand for `run add-feature`.
 #[derive(Debug, Args)]
 pub(crate) struct AddArgs {
     /// Feature description. Equivalent to `run add-feature --prompt "..."`.
     pub(crate) prompt: Option<String>,
     #[arg(long = "resume-from")]
     pub(crate) resume_from: Option<String>,
     #[arg(long = "run")]
     pub(crate) run_id: Option<String>,
     #[arg(long = "skip")]
     pub(crate) skip: Vec<String>,
     #[arg(long = "unskip")]
     pub(crate) unskip: Vec<String>,
     #[arg(long)]
     pub(crate) dry_run: bool,
     #[arg(long, help = "Alias for `--skip clarify`")]
     pub(crate) no_clarify: bool,
     #[arg(long, help = "Alias for `--skip assay`")]
     pub(crate) no_assay: bool,
     #[arg(long, help = "Skip the GitHub Issues creation offer")]
     pub(crate) no_github_issues: bool,
     /// Wipe prior run state and start fresh instead of auto-resuming.
     #[arg(long, help = "Discard any prior incomplete run and start from scratch")]
     pub(crate) force: bool,
 }

